10	type Item = { type: string };
11	
12	const RUNE = "rune";
13	const RUNE_BLOCK_SIZE = 3;
14	const RUNE_BLOCK_PRICE = 60;
15	
16	const sumOfItemPrices = (items: Item[]): number =>
17	  items.reduce((sum, item) => sum + priceList[item.type], 0);
18	
19	export const basePremium = (items: Item[]): number => {
20	  const runeCount = items.filter((item) => item.type === RUNE).length;
21	  if (runeCount === RUNE_BLOCK_SIZE) return RUNE_BLOCK_PRICE;
22	  return sumOfItemPrices(items);
23	};
